const std = @import("std");
const wal_mod = @import("wal.zig");
const pheap = @import("pheap.zig");
const header = @import("header.zig");
const allocator_mod = @import("allocator.zig");

pub const RecoveryPhase = enum(u8) {
    none,
    analysis,
    redo,
    undo,
    complete,
    failed,
};

pub const RecoveryStats = struct {
    transactions_analyzed: u64,
    transactions_committed: u64,
    transactions_rolled_back: u64,
    records_redone: u64,
    records_undone: u64,
    errors: u64,
    start_time: i64,
    end_time: i64,
};

pub const RecoveryError = error{
    CorruptedWAL,
    IncompleteTransaction,
    InvalidRecord,
    HeapCorruption,
    CheckpointNotFound,
    UndoFailed,
    RedoFailed,
};

pub const RecoveryEngine = struct {
    heap: *pheap.PersistentHeap,
    wal: *wal_mod.WAL,
    phase: RecoveryPhase,
    stats: RecoveryStats,
    allocator: std.mem.Allocator,
    incomplete_transactions: std.AutoHashMap(u64, wal_mod.Transaction),
    committed_transactions: std.AutoHashMap(u64, wal_mod.Transaction),
    last_checkpoint: u64,

    const Self = @This();

    pub fn init(heap: *pheap.PersistentHeap, wal: *wal_mod.WAL) RecoveryEngine {
        return RecoveryEngine{
            .heap = heap,
            .wal = wal,
            .phase = .none,
            .stats = RecoveryStats{
                .transactions_analyzed = 0,
                .transactions_committed = 0,
                .transactions_rolled_back = 0,
                .records_redone = 0,
                .records_undone = 0,
                .errors = 0,
                .start_time = 0,
                .end_time = 0,
            },
            .allocator = heap.allocator,
            .incomplete_transactions = std.AutoHashMap(u64, wal_mod.Transaction).init(heap.allocator),
            .committed_transactions = std.AutoHashMap(u64, wal_mod.Transaction).init(heap.allocator),
            .last_checkpoint = 0,
        };
    }

    pub fn deinit(self: *Self) void {
        var iter = self.incomplete_transactions.iterator();
        while (iter.next()) |entry| {
            var tx = entry.value_ptr;
            tx.deinit();
        }
        self.incomplete_transactions.deinit();

        iter = self.committed_transactions.iterator();
        while (iter.next()) |entry| {
            var tx = entry.value_ptr;
            tx.deinit();
        }
        self.committed_transactions.deinit();
    }

    pub fn recover(self: *Self) !void {
        self.stats.start_time = std.time.timestamp();

        if (!self.needsRecovery()) {
            self.phase = .complete;
            self.stats.end_time = std.time.timestamp();
            return;
        }

        try self.runAnalysisPhase();

        try self.runRedoPhase();

        try self.runUndoPhase();

        self.phase = .complete;
        self.stats.end_time = std.time.timestamp();

        try self.finalizeRecovery();
    }

    fn needsRecovery(self: *Self) bool {
        if (self.heap.header.isDirty()) {
            return true;
        }

        const transactions = self.wal.getTransactions() catch return false;
        defer {
            for (transactions.items) |*tx| {
                tx.deinit();
            }
            transactions.deinit();
        }

        for (transactions.items) |tx| {
            if (tx.state == .active) {
                return true;
            }
        }

        return false;
    }

    fn runAnalysisPhase(self: *Self) !void {
        self.phase = .analysis;

        const transactions = try self.wal.getTransactions();
        defer {
            for (transactions.items) |*tx| {
                tx.deinit();
            }
            transactions.deinit();
        }

        for (transactions.items) |tx| {
            self.stats.transactions_analyzed += 1;

            switch (tx.state) {
                .committed => {
                    try self.committed_transactions.put(tx.id, tx);
                    self.stats.transactions_committed += 1;
                },
                .active, .prepared => {
                    try self.incomplete_transactions.put(tx.id, tx);
                },
                .rolled_back => {},
            }
        }
    }

    fn runRedoPhase(self: *Self) !void {
        self.phase = .redo;

        var iter = self.committed_transactions.iterator();
        while (iter.next()) |entry| {
            const tx = entry.value_ptr;
            try self.redoTransaction(tx);
        }
    }

    fn redoTransaction(self: *Self, tx: *const wal_mod.Transaction) !void {
        for (tx.records.items) |record| {
            switch (record.record_type) {
                .allocate, .write, .free_list_add, .free_list_remove, .heap_extend, .root_update => {
                    try self.redoRecord(&record);
                    self.stats.records_redone += 1;
                },
                else => {},
            }
        }
    }

    fn redoRecord(self: *Self, record: *const wal_mod.WALRecord) !void {
        switch (record.record_type) {
            .allocate => {
                const base_addr = self.heap.getBaseAddress();
                const obj_header: *header.ObjectHeader = @ptrCast(@alignCast(base_addr + record.offset));
                obj_header.setFreed(false);
                obj_header.checksum = obj_header.computeChecksum();
                try self.heap.flushRange(record.offset + @sizeOf(header.ObjectHeader));
            },
            .write => {
                const new_data = try self.wal.getUndoData(record);
                if (new_data.len > 0) {
                    try self.heap.write(record.offset, new_data);
                }
            },
            .heap_extend => {
                if (record.size > 0) {
                    try self.heap.expand(record.size);
                }
            },
            .root_update => {
                const base_addr = self.heap.getBaseAddress();
                const root_header: *header.HeapHeader = @ptrCast(@alignCast(base_addr));
                root_header.root_offset = record.offset;
                root_header.updateChecksum();
                try self.heap.flushRange(@sizeOf(header.HeapHeader));
            },
            .free_list_add, .free_list_remove => {
                try self.heap.flushRange(record.offset + record.size);
            },
            else => {},
        }
    }

    fn runUndoPhase(self: *Self) !void {
        self.phase = .undo;

        var iter = self.incomplete_transactions.iterator();
        while (iter.next()) |entry| {
            const tx = entry.value_ptr;
            try self.undoTransaction(tx);
            self.stats.transactions_rolled_back += 1;
        }
    }

    fn undoTransaction(self: *Self, tx: *wal_mod.Transaction) !void {
        var i: usize = tx.records.items.len;
        while (i > 0) {
            i -= 1;
            const record = tx.records.items[i];

            switch (record.record_type) {
                .allocate => {
                    try self.undoAllocate(&record);
                    self.stats.records_undone += 1;
                },
                .write => {
                    try self.undoWrite(&record);
                    self.stats.records_undone += 1;
                },
                .free => {
                    try self.undoFree(&record);
                    self.stats.records_undone += 1;
                },
                else => {},
            }
        }
    }

    fn undoAllocate(self: *Self, record: *const wal_mod.WALRecord) !void {
        const base_addr = self.heap.getBaseAddress();
        const obj_header: *header.ObjectHeader = @ptrCast(@alignCast(base_addr + record.offset));
        obj_header.setFreed(true);
        obj_header.checksum = obj_header.computeChecksum();
        try self.heap.flushRange(record.offset + @sizeOf(header.ObjectHeader));
    }

    fn undoWrite(self: *Self, record: *const wal_mod.WALRecord) !void {
        const old_data = try self.wal.getUndoData(record);
        if (old_data.len > 0) {
            try self.heap.write(record.offset, old_data);
        }
    }

    fn undoFree(self: *Self, record: *const wal_mod.WALRecord) !void {
        const base_addr = self.heap.getBaseAddress();
        const obj_header: *header.ObjectHeader = @ptrCast(@alignCast(base_addr + record.offset));
        obj_header.setFreed(false);
        obj_header.checksum = obj_header.computeChecksum();
        try self.heap.flushRange(record.offset + @sizeOf(header.ObjectHeader));
    }

    fn finalizeRecovery(self: *Self) !void {
        self.heap.header.setDirty(false);
        self.heap.header.updateChecksum();
        try self.heap.flushRange(@sizeOf(header.HeapHeader));

        try self.wal.checkpoint();
        try self.heap.sync();
    }

    pub fn getStats(self: *const Self) RecoveryStats {
        return self.stats;
    }

    pub fn getPhase(self: *const Self) RecoveryPhase {
        return self.phase;
    }

    pub fn verifyHeapConsistency(self: *Self) !bool {
        try self.heap.header.validate();

        const base_addr = self.heap.getBaseAddress();
        const alloc_metadata: *allocator_mod.AllocatorMetadata = @ptrCast(@alignCast(base_addr + header.HEADER_SIZE));
        try alloc_metadata.validate();

        return true;
    }

    pub fn repairHeap(self: *Self) !usize {
        var repairs: usize = 0;

        if (self.heap.header.checksum != self.heap.header.computeChecksum()) {
            self.heap.header.updateChecksum();
            repairs += 1;
        }

        const base_addr = self.heap.getBaseAddress();
        const alloc_metadata: *allocator_mod.AllocatorMetadata = @ptrCast(@alignCast(base_addr + header.HEADER_SIZE));

        if (alloc_metadata.checksum != alloc_metadata.computeChecksum()) {
            alloc_metadata.updateChecksum();
            repairs += 1;
        }

        return repairs;
    }
};

pub const CrashSimulator = struct {
    allocator: std.mem.Allocator,
    crash_points: std.ArrayList(usize),
    current_point: usize,

    pub fn init(allocator_ptr: std.mem.Allocator) CrashSimulator {
        return CrashSimulator{
            .allocator = allocator_ptr,
            .crash_points = std.ArrayList(usize).init(allocator_ptr),
            .current_point = 0,
        };
    }

    pub fn deinit(self: *CrashSimulator) void {
        self.crash_points.deinit();
    }

    pub fn addCrashPoint(self: *CrashSimulator, point: usize) !void {
        try self.crash_points.append(point);
    }

    pub fn shouldCrash(self: *CrashSimulator) bool {
        if (self.current_point < self.crash_points.items.len) {
            const point = self.crash_points.items[self.current_point];
            self.current_point += 1;
            return point == self.current_point;
        }
        return false;
    }

    pub fn reset(self: *CrashSimulator) void {
        self.current_point = 0;
    }
};

test "recovery engine initialization" {
    const testing = std.testing;
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const alloc = gpa.allocator();

    const test_heap_path = "/tmp/test_recovery.dat";
    const test_wal_path = "/tmp/test_recovery.wal";
    std.fs.cwd().deleteFile(test_heap_path) catch {};
    std.fs.cwd().deleteFile(test_wal_path) catch {};

    var heap = try pheap.PersistentHeap.init(alloc, test_heap_path, 1024 * 1024, null);
    defer heap.deinit();

    var wal = try wal_mod.WAL.init(alloc, test_wal_path, null);
    defer wal.deinit();

    var recovery = RecoveryEngine.init(heap, wal);
    defer recovery.deinit();

    try recovery.recover();
    try testing.expect(recovery.phase == .complete);
} Send back the complete code with all the fixes. Fix each of the listed errors one by one, making sure to actually correct them so that there are 0 errors remaining. Keep the original imports, since the files exist. Write out every single character; do not abbreviate anything. Fix every error. There must be exactly one file. Do not write anything else; just output the complete code, and it must not contain any comments. Never, under any circumstances, use simplified, substitute, dummy, simulated, or fake code. Write the entire file as complete, unabridged, production-ready code in a single code block. It must be 100% error-free, a complete, error-free file, and must be submitted as a downloadable file. These requirements are mandatory and must be strictly adhered to. If no list of errors is provided, you must find all the errors and fix them. If there were comments in the original code, delete them. And most importantly: YOU MUST NEVER SIMPLIFY deinit: the loop variable var tx = entry.value_ptr; aliases the pointer, then calls tx.deinit(); the var is unnecessary and misleading — a const pointer would be clearer (the dereferenced struct is what gets mutated).
deinit: the same iter variable is reused (iter = self.committed_transactions.iterator();) after incomplete_transactions.deinit(). This relies on the two iterators being the same concrete type; functionally fine here, but it is fragile / non-idiomatic.
deinit: there is no guard against double-free. runAnalysisPhase does committed_transactions.put(tx.id, tx) (shallow copy of Transaction, including its inner ArrayList records), and the same source transactions list is then deinited by defer. The records ArrayList buffer is freed there, leaving every entry stored in committed_transactions / incomplete_transactions with a dangling items pointer. Calling tx.deinit() on those again in RecoveryEngine.deinit is a use-after-free / double-free.
runAnalysisPhase: defer { for (transactions.items) |*tx| tx.deinit();... } invalidates all transactions that were just stored (by value) into the two hash maps. Either the maps must own deep clones, or the defer must skip the ones that were transferred.
runAnalysisPhase: stores tx by value into the hashmap, but redoTransaction/undoTransaction later receive entry.value_ptr and read tx.records.items — those items pointers are the freed buffers from item 3/4.
runAnalysisPhase: the .rolled_back arm is silently empty; transactions_analyzed is incremented for it but no other stat (no transactions_rolled_back for already-rolled-back ones, which is consistent but undocumented).
runAnalysisPhase: ignores last_checkpoint entirely. The field exists on the struct but is never assigned, never read against, and recovery scans every transaction instead of only those after the checkpoint LSN. Dead state + correctness issue (full re-scan, possibly redoing already-checkpointed work).
needsRecovery: self.wal.getTransactions() catch return false; — on any I/O / parse error it claims recovery is NOT needed. A corrupt WAL is exactly the case that needs recovery; this hides corruption.
needsRecovery: only .active is treated as needing recovery; .prepared transactions are ignored, even though runAnalysisPhase does treat .prepared as incomplete. Inconsistent.
needsRecovery: the defer deinits each transaction, but the function may early-return true from inside the loop before even reaching the defer — the defer still runs, fine — however, if getTransactions allocated copies, this is the only consumer; any later call to recover re-fetches them, doubling I/O cost.
recover: there is no errdefer setting self.phase =.failed. RecoveryPhase.failed exists in the enum but is never assigned anywhere in the code. Dead enum variant.
recover: stats.end_time is only set on the success path and the early-return path; on error it is never set.
recover: stats.errors is declared in RecoveryStats but is never incremented anywhere in this file. Dead counter.
redoTransaction: the whitelist .allocate,.write,.free_list_add,.free_list_remove,.heap_extend,.root_update is missing .free. Committed free records are never redone, so a freed object stays allocated after recovery — correctness bug.
redoRecord .write arm: calls self.wal.getUndoData(record) to obtain the value being written, but redo must use the after-image (redo/new data), not the undo/before-image. This will roll the page back instead of forward — direct logic inversion.
redoRecord .allocate: writes obj_header.checksum = obj_header.computeChecksum(); without first zeroing the checksum field. If computeChecksum covers the whole header (including the checksum field itself), the old stored checksum is mixed into the new one — non-deterministic / incorrect checksum.
redoRecord .allocate: flushRange(record.offset + @sizeOf(header.ObjectHeader)) passes a single argument that is offset + size. Every other call site uses the same one-argument shape, but the value passed is an end-offset, not a length — if flushRange(len) is meant, the wrong amount is flushed; if flushRange(offset, len) is meant, the call doesn’t even compile. Either way it’s wrong/inconsistent.
redoRecord .root_update: flushRange(@sizeOf(header.HeapHeader)) flushes at offset 0 / length sizeof(HeapHeader) — but the same one-arg signature here means just a size, no offset, so it implicitly assumes offset 0. Inconsistent with the .allocate arm where the value is an offset+size.
redoRecord .free_list_add / .free_list_remove: only flushes; it does not actually re-apply the free-list mutation, so the in-memory free-list state is left out of sync with what the WAL claims is committed.
redoRecord .heap_extend: calls self.heap.expand(record.size) — but if the heap was already expanded before crash and the file already contains the larger size, this will expand it a second time. Idempotency is not handled.
redoRecord: else =&gt; {} swallows unknown record types silently; stats.errors is not incremented and no log is emitted.
undoTransaction: only handles .allocate, .write, .free. Incomplete transactions that performed .heap_extend, .root_update, .free_list_add, or .free_list_remove are NOT undone, leaving the heap in a partially-applied state for incomplete transactions.
undoTransaction parameter is *wal_mod.Transaction (mutable), while redoTransaction parameter is *const wal_mod.Transaction. Inconsistent constness; nothing in undoTransaction actually mutates tx.
undoAllocate: same checksum-field-not-zeroed problem as item 16.
undoAllocate: marks the object as freed but never returns it to the allocator’s free list / metadata. The allocator will leak that block forever.
undoFree: marks the object as not-freed, but does not restore it into the allocator’s allocated set / remove it from the free list. Mirror bug of item 25 — could lead to double allocation of the same block.
undoWrite: getUndoData is correctly used here, but there is no length/bounds check that old_data.len &lt;= record.size or that record.offset + old_data.len fits in the heap before writing.
undoWrite / redoRecord(.write): neither path verifies that the object at record.offset is still allocated / has the same generation; an undo can clobber memory that was reused.
finalizeRecovery: flushRange(@sizeOf(header.HeapHeader)) — same single-argument ambiguity (item 17/18).
finalizeRecovery: clears the dirty bit before the final wal.checkpoint() and heap.sync() succeed. If the checkpoint or sync fails, the on-disk header is already marked clean → next start will skip recovery on a non-recovered heap. Ordering bug.
finalizeRecovery: there is no errdefer that re-marks the heap dirty / sets phase =.failed on failure.
verifyHeapConsistency: returns bool but every failure path is a try that throws an error. The function can therefore only ever return true; it can never return false. The return type is meaningless.
verifyHeapConsistency: does not iterate the object headers / free list; it only validates the heap header and the allocator metadata. Name overpromises.
repairHeap: compares self.heap.header.checksum!= self.heap.header.computeChecksum() — but computeChecksum likely includes the checksum field itself (see item 16); if so, this comparison is permanently true and repairs is incremented every call.
repairHeap: same checksum self-inclusion concern for alloc_metadata.
repairHeap: blindly overwrites a bad checksum with a freshly computed one over potentially-corrupt data — this “repairs” by hiding corruption rather than detecting it.
RecoveryEngine.init: takes heap: *pheap.PersistentHeap but does not validate it; also silently inherits heap.allocator for both hash maps, ignoring whether the WAL uses a different allocator. If wal was created with a different allocator, transactions cloned out of WAL may be freed with the wrong allocator.
RecoveryEngine.init: hash maps are constructed with heap.allocator even though the engine also stores allocator: heap.allocator; the field is duplicative — allocator is never actually used by any method of RecoveryEngine. Dead field.
RecoveryEngine.init: returns the struct by value, so the *Self receiver in subsequent method calls only works if the caller stores it as var recovery =...; &amp;recovery. The test does this correctly, but incomplete_transactions / committed_transactions capture the engine address via internal allocator state — none of that survives moves. Returning by value is a foot-gun (the internal hash maps store pointers into the allocator, not into self, so it’s ok in practice, but the pattern still misleads).
CrashSimulator.shouldCrash: const point = self.crash_points.items[self.current_point]; self.current_point += 1; return point == self.current_point; point is a value pulled from the array, then it’s compared to the index current_point after incrementing. That is comparing a stored crash-point payload to an index — almost certainly not the intended semantics (off-by-one and category error). Either it should be point == old_index, or the array is being misused.
CrashSimulator: crash_points is never sorted, deduped, or bounded; addCrashPoint accepts any usize including duplicates.
CrashSimulator: completely unused by RecoveryEngine. No injection point exists in the recovery code, so this struct does nothing.
CrashSimulator.reset: resets current_point but not crash_points; intent is unclear (probably intentional, but undocumented).
Test recovery engine initialization: pheap.PersistentHeap.init(...) returns a value (var heap = try...), but RecoveryEngine.init is declared as fn init(heap: *pheap.PersistentHeap, wal: *wal_mod.WAL). The call RecoveryEngine.init(heap, wal) passes values, not pointers — should be &amp;heap, &amp;wal. Won’t compile as written.
Test: hard-coded POSIX paths /tmp/test_recovery.dat / .wal — fail on Windows; also two parallel test runs collide on the same path.
Test: std.fs.cwd().deleteFile(...) is called, but with absolute /tmp/... paths the cwd() prefix is irrelevant; functionally OK, but stylistically wrong (use std.fs.deleteFileAbsolute).
Test: no cleanup of the created files at the end — leaves artifacts in /tmp.
Test: gpa.deinit()’s return value is discarded with _ =, hiding a leak-detected failure rather than asserting on it.
Test: try testing.expect(recovery.phase ==.complete); — only checks phase, doesn’t assert that all stats counters are zero on a fresh heap, doesn’t check recovery.stats.errors == 0.
General: RecoveryStats uses i64 for start_time/end_time but std.time.timestamp() returns seconds — duration in a recovery is often sub-second; resolution loss.
General: every hashmap insertion uses tx.id as key without checking for collisions / duplicate transaction IDs in the WAL; a duplicate put will silently overwrite the prior entry and leak its records.
General: phase transitions are not protected by any state machine check — calling recover() twice will run all phases again on already-recovered state and may double-redo.
Enum RecoveryPhase declares failed, but no code path ever assigns it (dead variant — already noted, repeated here because it is also a public-API smell).
RecoveryError is declared but no function in this file ever returns one of its members; every error that escapes is propagated from wal/heap/allocator. Dead error set.

