```zig
const std = @import("std");
const wal_mod = @import("wal.zig");
const pheap = @import("pheap.zig");
const header = @import("header.zig");
const allocator_mod = @import("allocator.zig");

pub const RecoveryPhase = enum(u8) {
    none,
    analysis,
    redo,
    undo,
    complete,
    failed,
};

pub const RecoveryStats = struct {
    transactions_analyzed: u64,
    transactions_committed: u64,
    transactions_rolled_back: u64,
    records_redone: u64,
    records_undone: u64,
    errors: u64,
    start_time_ns: i128,
    end_time_ns: i128,
};

pub const RecoveryError = error{
    CorruptedWAL,
    IncompleteTransaction,
    InvalidRecord,
    HeapCorruption,
    CheckpointNotFound,
    UndoFailed,
    RedoFailed,
    DuplicateTransactionId,
    InvalidBounds,
    UnsupportedRecord,
    RecoveryAlreadyRunning,
};

pub const RecoveryEngine = struct {
    heap: *pheap.PersistentHeap,
    wal: *wal_mod.WAL,
    phase: RecoveryPhase,
    stats: RecoveryStats,
    allocator: std.mem.Allocator,
    incomplete_transactions: std.AutoHashMap(u64, wal_mod.Transaction),
    committed_transactions: std.AutoHashMap(u64, wal_mod.Transaction),
    last_checkpoint: u64,

    const Self = @This();

    pub fn init(heap: *pheap.PersistentHeap, wal: *wal_mod.WAL) !RecoveryEngine {
        try heap.header.validate();
        return RecoveryEngine{
            .heap = heap,
            .wal = wal,
            .phase = .none,
            .stats = RecoveryStats{
                .transactions_analyzed = 0,
                .transactions_committed = 0,
                .transactions_rolled_back = 0,
                .records_redone = 0,
                .records_undone = 0,
                .errors = 0,
                .start_time_ns = 0,
                .end_time_ns = 0,
            },
            .allocator = heap.allocator,
            .incomplete_transactions = std.AutoHashMap(u64, wal_mod.Transaction).init(heap.allocator),
            .committed_transactions = std.AutoHashMap(u64, wal_mod.Transaction).init(heap.allocator),
            .last_checkpoint = 0,
        };
    }

    pub fn deinit(self: *Self) void {
        var incomplete_iter = self.incomplete_transactions.iterator();
        while (incomplete_iter.next()) |entry| {
            entry.value_ptr.deinit();
        }
        self.incomplete_transactions.deinit();

        var committed_iter = self.committed_transactions.iterator();
        while (committed_iter.next()) |entry| {
            entry.value_ptr.deinit();
        }
        self.committed_transactions.deinit();

        self.phase = .none;
    }

    pub fn recover(self: *Self) !void {
        if (self.phase != .none and self.phase != .complete and self.phase != .failed) {
            self.stats.errors += 1;
            self.phase = .failed;
            self.stats.end_time_ns = std.time.nanoTimestamp();
            return RecoveryError.RecoveryAlreadyRunning;
        }

        self.stats.start_time_ns = std.time.nanoTimestamp();
        self.stats.end_time_ns = 0;
        errdefer {
            self.phase = .failed;
            self.stats.errors += 1;
            self.stats.end_time_ns = std.time.nanoTimestamp();
            self.heap.header.setDirty(true);
            self.heap.header.checksum = 0;
            self.heap.header.updateChecksum();
            _ = self.heap.flushRange(0, @sizeOf(header.HeapHeader)) catch {};
            _ = self.heap.sync() catch {};
        }

        if (!try self.needsRecovery()) {
            self.phase = .complete;
            self.stats.end_time_ns = std.time.nanoTimestamp();
            return;
        }

        try self.runAnalysisPhase();
        try self.runRedoPhase();
        try self.runUndoPhase();
        try self.finalizeRecovery();

        self.phase = .complete;
        self.stats.end_time_ns = std.time.nanoTimestamp();
    }

    fn needsRecovery(self: *Self) !bool {
        if (self.heap.header.isDirty()) {
            return true;
        }

        const transactions = try self.wal.getTransactions();
        defer {
            for (transactions.items) |*tx| {
                tx.deinit();
            }
            transactions.deinit();
        }

        for (transactions.items) |tx| {
            if (self.transactionRequiresRecovery(&tx)) {
                return true;
            }
        }

        return false;
    }

    fn runAnalysisPhase(self: *Self) !void {
        self.phase = .analysis;
        self.last_checkpoint = try self.readLastCheckpoint();

        const transactions = try self.wal.getTransactions();
        defer {
            for (transactions.items) |*tx| {
                tx.deinit();
            }
            transactions.deinit();
        }

        for (transactions.items) |tx| {
            if (!self.transactionIsAfterCheckpoint(&tx)) {
                continue;
            }

            self.stats.transactions_analyzed += 1;

            switch (tx.state) {
                .committed => {
                    if (self.committed_transactions.contains(tx.id) or self.incomplete_transactions.contains(tx.id)) {
                        return RecoveryError.DuplicateTransactionId;
                    }
                    const tx_copy = try self.cloneTransaction(&tx);
                    try self.committed_transactions.put(tx.id, tx_copy);
                    self.stats.transactions_committed += 1;
                },
                .active, .prepared => {
                    if (self.incomplete_transactions.contains(tx.id) or self.committed_transactions.contains(tx.id)) {
                        return RecoveryError.DuplicateTransactionId;
                    }
                    const tx_copy = try self.cloneTransaction(&tx);
                    try self.incomplete_transactions.put(tx.id, tx_copy);
                },
                .rolled_back => {
                    self.stats.transactions_rolled_back += 1;
                },
                else => {
                    self.stats.errors += 1;
                    return RecoveryError.InvalidRecord;
                },
            }
        }
    }

    fn runRedoPhase(self: *Self) !void {
        self.phase = .redo;

        var iter = self.committed_transactions.iterator();
        while (iter.next()) |entry| {
            try self.redoTransaction(entry.value_ptr);
        }
    }

    fn redoTransaction(self: *Self, tx: *const wal_mod.Transaction) !void {
        for (tx.records.items) |record| {
            switch (record.record_type) {
                .allocate, .write, .free, .free_list_add, .free_list_remove, .heap_extend, .root_update => {
                    try self.redoRecord(&record);
                    self.stats.records_redone += 1;
                },
                else => {
                    self.stats.errors += 1;
                    return RecoveryError.UnsupportedRecord;
                },
            }
        }
    }

    fn redoRecord(self: *Self, record: *const wal_mod.WALRecord) !void {
        try self.validateRecordBounds(record);

        switch (record.record_type) {
            .allocate => {
                const base_addr = self.heap.getBaseAddress();
                const obj_header: *header.ObjectHeader = @ptrCast(@alignCast(base_addr + record.offset));
                obj_header.setFreed(false);
                obj_header.checksum = 0;
                obj_header.checksum = obj_header.computeChecksum();
                try self.heap.flushRange(record.offset, @sizeOf(header.ObjectHeader));
            },
            .write => {
                const new_data = try self.getRedoData(record);
                if (new_data.len > 0) {
                    try self.validateWriteBounds(record.offset, new_data.len);
                    try self.heap.write(record.offset, new_data);
                }
            },
            .free => {
                const base_addr = self.heap.getBaseAddress();
                const obj_header: *header.ObjectHeader = @ptrCast(@alignCast(base_addr + record.offset));
                obj_header.setFreed(true);
                obj_header.checksum = 0;
                obj_header.checksum = obj_header.computeChecksum();
                try self.heap.flushRange(record.offset, @sizeOf(header.ObjectHeader));
            },
            .heap_extend => {
                if (record.size > 0) {
                    const current_size = try self.getHeapSize();
                    const required_size = record.offset + record.size;
                    if (current_size < required_size) {
                        try self.heap.expand(required_size - current_size);
                    }
                }
            },
            .root_update => {
                const base_addr = self.heap.getBaseAddress();
                const root_header: *header.HeapHeader = @ptrCast(@alignCast(base_addr));
                root_header.root_offset = record.offset;
                root_header.checksum = 0;
                root_header.updateChecksum();
                try self.heap.flushRange(0, @sizeOf(header.HeapHeader));
            },
            .free_list_add => {
                try self.applyFreeListAdd(record);
            },
            .free_list_remove => {
                try self.applyFreeListRemove(record);
            },
            else => {
                self.stats.errors += 1;
                return RecoveryError.UnsupportedRecord;
            },
        }
    }

    fn runUndoPhase(self: *Self) !void {
        self.phase = .undo;

        var iter = self.incomplete_transactions.iterator();
        while (iter.next()) |entry| {
            try self.undoTransaction(entry.value_ptr);
            self.stats.transactions_rolled_back += 1;
        }
    }

    fn undoTransaction(self: *Self, tx: *const wal_mod.Transaction) !void {
        var i: usize = tx.records.items.len;
        while (i > 0) {
            i -= 1;
            const record = tx.records.items[i];

            switch (record.record_type) {
                .allocate => {
                    try self.undoAllocate(&record);
                    self.stats.records_undone += 1;
                },
                .write => {
                    try self.undoWrite(&record);
                    self.stats.records_undone += 1;
                },
                .free => {
                    try self.undoFree(&record);
                    self.stats.records_undone += 1;
                },
                .heap_extend => {
                    try self.undoHeapExtend(&record);
                    self.stats.records_undone += 1;
                },
                .root_update => {
                    try self.undoRootUpdate(&record);
                    self.stats.records_undone += 1;
                },
                .free_list_add => {
                    try self.undoFreeListAdd(&record);
                    self.stats.records_undone += 1;
                },
                .free_list_remove => {
                    try self.undoFreeListRemove(&record);
                    self.stats.records_undone += 1;
                },
                else => {
                    self.stats.errors += 1;
                    return RecoveryError.UnsupportedRecord;
                },
            }
        }
    }

    fn undoAllocate(self: *Self, record: *const wal_mod.WALRecord) !void {
        try self.validateRecordBounds(record);
        const base_addr = self.heap.getBaseAddress();
        const obj_header: *header.ObjectHeader = @ptrCast(@alignCast(base_addr + record.offset));
        obj_header.setFreed(true);
        obj_header.checksum = 0;
        obj_header.checksum = obj_header.computeChecksum();
        try self.heap.flushRange(record.offset, @sizeOf(header.ObjectHeader));
        try self.applyFreeListAdd(record);
    }

    fn undoWrite(self: *Self, record: *const wal_mod.WALRecord) !void {
        try self.validateRecordBounds(record);
        const old_data = try self.wal.getUndoData(record);
        if (old_data.len > 0) {
            try self.validateWriteBounds(record.offset, old_data.len);
            try self.ensureObjectHeaderPresent(record.offset);
            try self.heap.write(record.offset, old_data);
        }
    }

    fn undoFree(self: *Self, record: *const wal_mod.WALRecord) !void {
        try self.validateRecordBounds(record);
        const base_addr = self.heap.getBaseAddress();
        const obj_header: *header.ObjectHeader = @ptrCast(@alignCast(base_addr + record.offset));
        obj_header.setFreed(false);
        obj_header.checksum = 0;
        obj_header.checksum = obj_header.computeChecksum();
        try self.heap.flushRange(record.offset, @sizeOf(header.ObjectHeader));
        try self.applyFreeListRemove(record);
    }

    fn undoHeapExtend(self: *Self, record: *const wal_mod.WALRecord) !void {
        _ = self;
        _ = record;
    }

    fn undoRootUpdate(self: *Self, record: *const wal_mod.WALRecord) !void {
        const undo_offset = try self.getUndoRootOffset(record);
        const base_addr = self.heap.getBaseAddress();
        const root_header: *header.HeapHeader = @ptrCast(@alignCast(base_addr));
        root_header.root_offset = undo_offset;
        root_header.checksum = 0;
        root_header.updateChecksum();
        try self.heap.flushRange(0, @sizeOf(header.HeapHeader));
    }

    fn undoFreeListAdd(self: *Self, record: *const wal_mod.WALRecord) !void {
        try self.applyFreeListRemove(record);
    }

    fn undoFreeListRemove(self: *Self, record: *const wal_mod.WALRecord) !void {
        try self.applyFreeListAdd(record);
    }

    fn finalizeRecovery(self: *Self) !void {
        errdefer {
            self.phase = .failed;
            self.stats.errors += 1;
            self.heap.header.setDirty(true);
            self.heap.header.checksum = 0;
            self.heap.header.updateChecksum();
            _ = self.heap.flushRange(0, @sizeOf(header.HeapHeader)) catch {};
            _ = self.heap.sync() catch {};
        }

        try self.wal.checkpoint();
        try self.heap.sync();

        self.heap.header.setDirty(false);
        self.heap.header.checksum = 0;
        self.heap.header.updateChecksum();
        try self.heap.flushRange(0, @sizeOf(header.HeapHeader));
        try self.heap.sync();
    }

    pub fn getStats(self: *const Self) RecoveryStats {
        return self.stats;
    }

    pub fn getPhase(self: *const Self) RecoveryPhase {
        return self.phase;
    }

    pub fn verifyHeapConsistency(self: *Self) !void {
        try self.heap.header.validate();

        const base_addr = self.heap.getBaseAddress();
        const alloc_metadata: *allocator_mod.AllocatorMetadata = @ptrCast(@alignCast(base_addr + header.HEADER_SIZE));
        try alloc_metadata.validate();

        try self.verifyRootOffset();
    }

    pub fn repairHeap(self: *Self) !usize {
        var repairs: usize = 0;

        if (!self.heapHeaderChecksumValid()) {
            self.heap.header.checksum = 0;
            self.heap.header.updateChecksum();
            repairs += 1;
        }

        const base_addr = self.heap.getBaseAddress();
        const alloc_metadata: *allocator_mod.AllocatorMetadata = @ptrCast(@alignCast(base_addr + header.HEADER_SIZE));

        if (!self.allocatorMetadataChecksumValid(alloc_metadata)) {
            alloc_metadata.checksum = 0;
            alloc_metadata.updateChecksum();
            repairs += 1;
        }

        if (repairs > 0) {
            try self.heap.flushRange(0, header.HEADER_SIZE + @sizeOf(allocator_mod.AllocatorMetadata));
            try self.heap.sync();
        }

        return repairs;
    }

    fn transactionRequiresRecovery(self: *Self, tx: *const wal_mod.Transaction) bool {
        if (!self.transactionIsAfterCheckpoint(tx)) {
            return false;
        }

        return switch (tx.state) {
            .active, .prepared, .committed => true,
            .rolled_back => false,
            else => true,
        };
    }

    fn transactionIsAfterCheckpoint(self: *Self, tx: *const wal_mod.Transaction) bool {
        if (self.last_checkpoint == 0) {
            return true;
        }
        return tx.id > self.last_checkpoint;
    }

    fn readLastCheckpoint(self: *Self) !u64 {
        if (@hasDecl(@TypeOf(self.wal.*), "getLastCheckpoint")) {
            return self.wal.getLastCheckpoint();
        }
        return 0;
    }

    fn cloneTransaction(self: *Self, tx: *const wal_mod.Transaction) !wal_mod.Transaction {
        if (@hasDecl(@TypeOf(tx.*), "clone")) {
            return tx.clone(self.allocator);
        }

        var tx_copy = wal_mod.Transaction.init(self.allocator, tx.id);
        errdefer tx_copy.deinit();

        tx_copy.state = tx.state;

        for (tx.records.items) |record| {
            try tx_copy.records.append(record);
        }

        return tx_copy;
    }

    fn validateRecordBounds(self: *Self, record: *const wal_mod.WALRecord) !void {
        const heap_size = try self.getHeapSize();

        if (record.offset > heap_size) {
            return RecoveryError.InvalidBounds;
        }

        if (record.size > 0 and record.offset + record.size > heap_size and record.record_type != .heap_extend) {
            return RecoveryError.InvalidBounds;
        }
    }

    fn validateWriteBounds(self: *Self, offset: usize, len: usize) !void {
        const heap_size = try self.getHeapSize();
        if (offset > heap_size or len > heap_size or offset + len > heap_size) {
            return RecoveryError.InvalidBounds;
        }
    }

    fn getHeapSize(self: *Self) !usize {
        if (@hasDecl(@TypeOf(self.heap.*), "getSize")) {
            return self.heap.getSize();
        }
        if (@hasField(@TypeOf(self.heap.*), "size")) {
            return self.heap.size;
        }
        return RecoveryError.HeapCorruption;
    }

    fn getRedoData(self: *Self, record: *const wal_mod.WALRecord) ![]const u8 {
        if (@hasDecl(@TypeOf(self.wal.*), "getRedoData")) {
            return self.wal.getRedoData(record);
        }
        return RecoveryError.RedoFailed;
    }

    fn getUndoRootOffset(self: *Self, record: *const wal_mod.WALRecord) !u64 {
        if (@hasDecl(@TypeOf(self.wal.*), "getUndoRootOffset")) {
            return self.wal.getUndoRootOffset(record);
        }

        const undo_data = try self.wal.getUndoData(record);
        if (undo_data.len < @sizeOf(u64)) {
            return RecoveryError.InvalidRecord;
        }

        return std.mem.readIntLittle(u64, undo_data[0..@sizeOf(u64)]);
    }

    fn ensureObjectHeaderPresent(self: *Self, offset: usize) !void {
        const heap_size = try self.getHeapSize();
        if (offset + @sizeOf(header.ObjectHeader) > heap_size) {
            return RecoveryError.InvalidBounds;
        }
        const base_addr = self.heap.getBaseAddress();
        const obj_header: *header.ObjectHeader = @ptrCast(@alignCast(base_addr + offset));
        _ = obj_header;
    }

    fn verifyRootOffset(self: *Self) !void {
        const heap_size = try self.getHeapSize();
        if (self.heap.header.root_offset > heap_size) {
            return RecoveryError.HeapCorruption;
        }
    }

    fn heapHeaderChecksumValid(self: *Self) bool {
        const saved = self.heap.header.checksum;
        self.heap.header.checksum = 0;
        const computed = self.heap.header.computeChecksum();
        self.heap.header.checksum = saved;
        return saved == computed;
    }

    fn allocatorMetadataChecksumValid(self: *Self, alloc_metadata: *allocator_mod.AllocatorMetadata) bool {
        _ = self;
        const saved = alloc_metadata.checksum;
        alloc_metadata.checksum = 0;
        const computed = alloc_metadata.computeChecksum();
        alloc_metadata.checksum = saved;
        return saved == computed;
    }

    fn applyFreeListAdd(self: *Self, record: *const wal_mod.WALRecord) !void {
        if (@hasDecl(@TypeOf(self.heap.*), "redoFreeListAdd")) {
            try self.heap.redoFreeListAdd(record.offset, record.size);
            return;
        }
        if (@hasDecl(@TypeOf(self.heap.*), "freeListAdd")) {
            try self.heap.freeListAdd(record.offset, record.size);
            return;
        }
        try self.heap.flushRange(record.offset, record.size);
    }

    fn applyFreeListRemove(self: *Self, record: *const wal_mod.WALRecord) !void {
        if (@hasDecl(@TypeOf(self.heap.*), "redoFreeListRemove")) {
            try self.heap.redoFreeListRemove(record.offset, record.size);
            return;
        }
        if (@hasDecl(@TypeOf(self.heap.*), "freeListRemove")) {
            try self.heap.freeListRemove(record.offset, record.size);
            return;
        }
        try self.heap.flushRange(record.offset, record.size);
    }
};

pub const CrashSimulator = struct {
    allocator: std.mem.Allocator,
    crash_points: std.ArrayList(usize),
    current_step: usize,

    pub fn init(allocator_ptr: std.mem.Allocator) CrashSimulator {
        return CrashSimulator{
            .allocator = allocator_ptr,
            .crash_points = std.ArrayList(usize).init(allocator_ptr),
            .current_step = 0,
        };
    }

    pub fn deinit(self: *CrashSimulator) void {
        self.crash_points.deinit();
    }

    pub fn addCrashPoint(self: *CrashSimulator, point: usize) !void {
        if (point == 0) {
            return;
        }

        for (self.crash_points.items) |existing| {
            if (existing == point) {
                return;
            }
        }

        try self.crash_points.append(point);
        std.sort.pdq(usize, self.crash_points.items, {}, comptime std.sort.asc(usize));
    }

    pub fn shouldCrash(self: *CrashSimulator) bool {
        self.current_step += 1;

        if (self.crash_points.items.len == 0) {
            return false;
        }

        return std.mem.indexOfScalar(usize, self.crash_points.items, self.current_step) != null;
    }

    pub fn reset(self: *CrashSimulator) void {
        self.current_step = 0;
    }
};

